// generated by gemini-3.5-flash-lite for PR #6009 (round 0): bon8_output_basic
// intent: Verify that converting a JSON object to BON8 using a vector sink produces output.
#include <nlohmann/json.hpp>
#include <vector>
#include <iostream>

int main() {
    nlohmann::json j = {{"key", "value"}};
    std::vector<std::uint8_t> v;
    try {
        nlohmann::json::to_bon8(j, v);
        std::cout << "size: " << v.size() << "\n";
    } catch (const std::exception& e) {
        std::cout << "exception: " << e.what() << "\n";
    }
    return 0;
}
